<section class="admin-panel">
    <div class="admin-panel-heading"><div><h2>Patient processing queue</h2><p>Live visit records and current workflow stage.</p></div><div class="reception-filter"><label for="queue-status">Filter status</label><select id="queue-status" data-queue-status><option value="">All statuses</option><option value="emergency_in_progress">Emergency in progress</option><option value="awaiting_ticket_payment">Awaiting ticket payment</option><option value="awaiting_nurse">Awaiting nursing</option><option value="awaiting_tests">Awaiting tests</option><option value="awaiting_doctor">Awaiting doctor</option><option value="awaiting_specialist">Awaiting specialist</option><option value="awaiting_therapy">Awaiting therapy</option><option value="awaiting_pharmacy">Awaiting pharmacy</option><option value="awaiting_payment">Awaiting payment</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div></div>
    <div class="table-wrap"><table class="admin-table reception-table"><thead><tr><th>Visit</th><th>Patient</th><th>Age / gender</th><th>Arrived</th><th>Reason</th><th>Route</th><th>Status</th></tr></thead><tbody data-queue-rows><tr><td class="table-message" colspan="7">Loading queue…</td></tr></tbody></table></div>
